const data = $json;

const missingFields = [];
const invalidFields = [];

if (!data.event_type) {
  missingFields.push('event_type');
} else if (data.event_type !== 'appointment.booking.created') {
  invalidFields.push('event_type');
}

if (!data.appointment_uuid) {
  missingFields.push('appointment_uuid');
}

if (!data.appointment_start_utc) {
  missingFields.push('appointment_start_utc');
}

if (!data.customer_uuid) {
  missingFields.push('customer_uuid');
}

if (!data.email) {
  missingFields.push('email');
} else {
  const email = String(data.email).trim();

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!emailRegex.test(email)) {
    invalidFields.push('email');
  }
}

if (data.phone !== null && data.phone !== undefined) {
  const phone = String(data.phone).trim();

  if (phone === '') {
    invalidFields.push('phone');
  }
}

const validationStatus =
  missingFields.length === 0 && invalidFields.length === 0
    ? 'OK'
    : 'REVIEW_REQUIRED';

return [
  {
    json: {
      ...data,
      validation_status: validationStatus,
      missing_fields: missingFields,
      invalid_fields: invalidFields,
    },
  },
];

const data = $json;

// EMAIL NORMALIZATION
let normalizedEmail = null;

if (data.email) {
  normalizedEmail = String(data.email)
    .trim()
    .toLowerCase();

  // Google requires dots before @ to be removed for Gmail / Googlemail
  const [localPart, domain] = normalizedEmail.split('@');

  if (
    localPart &&
    domain &&
    (domain === 'gmail.com' || domain === 'googlemail.com')
  ) {
    normalizedEmail = localPart.replace(/\./g, '') + '@' + domain;
  }
}

// PHONE NORMALIZATION
function normalizePhone(value) {
  if (value === null || value === undefined) {
    return null;
  }

  const rawPhone = String(value).trim();

  if (rawPhone === '' || /[A-Za-z]/.test(rawPhone)) {
    return null;
  }

  const compactPhone = rawPhone.replace(/[\s\-()./]/g, '');

  if ((compactPhone.match(/\+/g) || []).length > 1) {
    return null;
  }

  let normalizedPhone = null;

  if (compactPhone.startsWith('+')) {
    normalizedPhone = compactPhone;
  } else if (compactPhone.startsWith('00')) {
    normalizedPhone = '+' + compactPhone.slice(2);
  } else if (compactPhone.startsWith('0')) {
    normalizedPhone = '+49' + compactPhone.slice(1);
  } else {
    return null;
  }

  if (/^\+[1-9]\d{7,14}$/.test(normalizedPhone)) {
    return normalizedPhone;
  }

  return null;
}

const normalizedPhone = normalizePhone(data.phone);

return [
  {
    json: {
      ...data,
      normalized_email: normalizedEmail,
      normalized_phone: normalizedPhone,
    },
  },
];

function sha256(input) {
  function rightRotate(value, amount) {
    return (value >>> amount) | (value << (32 - amount));
  }

  const bytes = [];
  for (let i = 0; i < input.length; i += 1) {
    const code = input.charCodeAt(i);
    if (code > 0xff) {
      throw new Error('Phone identifier must contain ASCII characters only');
    }
    bytes.push(code);
  }

  const bitLength = bytes.length * 8;
  bytes.push(0x80);
  while ((bytes.length % 64) !== 56) {
    bytes.push(0);
  }

  for (let shift = 56; shift >= 0; shift -= 8) {
    bytes.push((bitLength / Math.pow(2, shift)) & 0xff);
  }

  const h = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
  ];

  const k = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
    0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
    0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
    0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
    0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
    0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];

  for (let chunk = 0; chunk < bytes.length; chunk += 64) {
    const w = new Array(64);

    for (let i = 0; i < 16; i += 1) {
      const j = chunk + i * 4;
      w[i] = (
        (bytes[j] << 24) |
        (bytes[j + 1] << 16) |
        (bytes[j + 2] << 8) |
        bytes[j + 3]
      ) >>> 0;
    }

    for (let i = 16; i < 64; i += 1) {
      const s0 = rightRotate(w[i - 15], 7) ^ rightRotate(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rightRotate(w[i - 2], 17) ^ rightRotate(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }

    let [a, b, c, d, e, f, g, hh] = h;

    for (let i = 0; i < 64; i += 1) {
      const s1 = rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25);
      const ch = (e & f) ^ ((~e) & g);
      const temp1 = (hh + s1 + ch + k[i] + w[i]) >>> 0;
      const s0 = rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (s0 + maj) >>> 0;

      hh = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }

    h[0] = (h[0] + a) >>> 0;
    h[1] = (h[1] + b) >>> 0;
    h[2] = (h[2] + c) >>> 0;
    h[3] = (h[3] + d) >>> 0;
    h[4] = (h[4] + e) >>> 0;
    h[5] = (h[5] + f) >>> 0;
    h[6] = (h[6] + g) >>> 0;
    h[7] = (h[7] + hh) >>> 0;
  }

  return h.map((value) => value.toString(16).padStart(8, '0')).join('');
}

return items.map((item) => {
  const json = { ...item.json };
  const normalizedPhone = json.normalized_phone;

  if (normalizedPhone && /^\+[1-9]\d{7,14}$/.test(String(normalizedPhone))) {
    json.hashed_phone = sha256(String(normalizedPhone));
  } else {
    json.hashed_phone = null;
  }

  delete json.phone;
  delete json.normalized_phone;

  return { json };
});
